// Generated by vuetify-ext bootstrap theme
import { ref, watch } from 'vue';

export type AppThemeMode = 'light' | 'dark';

export const APP_THEME_STORAGE_KEY = 'vuetify-extended-theme-mode';

function loadStoredThemeMode(): AppThemeMode {
  if (typeof window === 'undefined') {
    return "light";
  }

  const stored = window.localStorage.getItem(APP_THEME_STORAGE_KEY);
  if (stored === 'light' || stored === 'dark') {
    return stored;
  }

  return "light";
}

export const themeModeRef = ref<AppThemeMode>(loadStoredThemeMode());

watch(themeModeRef, (value) => {
  if (typeof window === 'undefined') {
    return;
  }

  try {
    window.localStorage.setItem(APP_THEME_STORAGE_KEY, value);
  } catch (_error) {
    //
  }
}, { immediate: true });

export function getThemeMode(): AppThemeMode {
  return themeModeRef.value;
}

export function setThemeMode(mode: AppThemeMode) {
  themeModeRef.value = mode;
  return mode;
}

export function toggleThemeMode(): AppThemeMode {
  const nextMode = getThemeMode() === 'dark' ? 'light' : 'dark';
  return setThemeMode(nextMode);
}

export function bindVuetifyThemeMode(vuetify: any) {
  watch(themeModeRef, (value) => {
    if (typeof vuetify?.theme?.change === 'function') {
      vuetify.theme.change(value);
      return;
    }

    if (vuetify?.theme?.global?.name) {
      vuetify.theme.global.name.value = value;
    }
  }, { immediate: true });
}

export function createVuetifyThemeOptions() {
  return {
    defaultTheme: getThemeMode(),
    themes: {
      light: {
        dark: false,
        colors: {
          primary: '#1867c0',
          secondary: '#5cbbf6',
          success: '#2e7d32',
          info: '#0288d1',
          warning: '#ed6c02',
          error: '#d32f2f',
          background: '#f5f7fb',
          surface: '#ffffff',
        },
      },
      dark: {
        dark: true,
        colors: {
          primary: '#90caf9',
          secondary: '#80cbc4',
          success: '#81c784',
          info: '#4fc3f7',
          warning: '#ffb74d',
          error: '#ef9a9a',
          background: '#0f172a',
          surface: '#111827',
        },
      },
    },
  };
}
